import {mathLessons,mathLevels,mathSteps,mathWords,normalizeMath,mathQuestionId} from './math-data.js';
import {mathScene,mathChoice,animateMathScene} from './math-scenes.js';
import {narrationLine,narrationControls} from './narration.js';
// Bangla translations that the lessons already contain, by English sentence.
const lessonBangla=new Map(mathLessons.flatMap(l=>[l,l.extra].filter(Boolean).flatMap(x=>[...(x.sentences||[]),...(x.questions||[])])).map(s=>[s.text||s.prompt,s.meaning]));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,attributes='',kind='')=>'<button class="btn '+kind+'" data-action="stages-math-'+action+'" '+attributes+'>'+label+'</button>';
const pause=()=>'<button class="btn" data-action="stages-pause" disabled aria-pressed="false">Pause</button>';
const meaning=text=>'<details class="math-meaning"><summary lang="bn">মানে · Bangla help</summary><p lang="bn">'+esc(text)+'</p></details>';
export function createMathFlow({getProgress,save,render,play,stop,onAttempt,isSaved}){
 let selected=null,stopMotion=()=>{},lastBound=null;
 const state=()=>getProgress().math,lesson=()=>mathLessons.find(l=>l.id===selected),p=()=>state().lessons[selected];
 function ensure(){getProgress().math??=normalizeMath(null);}
 const steps=()=>mathSteps(lesson(),p().extra),index=()=>p().extra?p().extraStep:p().step,current=()=>steps()[index()];
 function setIndex(n){if(p().extra)p().extraStep=n;else p().step=n;}
 function attempt(q){return p().attempts[q.id]??={tries:0,misses:0,assisted:false,firstCorrect:null};}
 function correct(q){return p().answers[q.id]===q.answer;}
 function levelPicker(){return '<details class="math-parent-level"><summary>For parents · Choose a learning level</summary><p>Choose by your child’s familiarity with counting and English. This suggests a starting point; all twelve lessons stay visible and open to every learner. Change level whenever you like. Read together when words are new.</p><label for="math-level">Learning level</label><select id="math-level">'+mathLevels.map(l=>'<option value="'+l.id+'" '+(state().level===l.id?'selected':'')+'>'+l.label+'</option>').join('')+'</select><p>'+esc(mathLevels[state().level].description)+'</p></details>';}
 function home(){ensure();const currentLesson=mathLessons.find(l=>l.id===state().current);return '<section class="math-library"><div class="eyebrow">English for Math · All learning ages</div><h1>Little stories, little numbers</h1><p>All 12 lessons · Start with counting, then explore in order.</p>'+levelPicker()+(currentLesson?'<div class="resume-strip"><span>'+esc(currentLesson.title)+'</span>'+btn('Continue your saved lesson →','open','data-id="'+currentLesson.id+'"','primary')+'</div>':'')+'<div class="math-lesson-cards">'+mathLessons.map((l,n)=>{const cur=l.id===state().current,next=!cur&&mathLessons[n-1]?.id===state().current;return '<button class="math-lesson-card'+(cur?' is-current':'')+(state().lessons[l.id]?.done?' is-done':'')+'" data-action="stages-math-open" data-id="'+l.id+'" aria-current="'+(cur?'true':'false')+'"><em class="lesson-number" aria-label="Lesson '+(n+1)+'">'+(n+1)+'</em>'+mathScene(l.questions[0].scene,true)+'<b>'+esc(l.title)+'</b><span>'+(state().lessons[l.id]?.done?'Practised ★':cur?'Continue here':next?'Up next':state().lessons[l.id]?'Continue saved place':l.level<=state().level?'Suggested starting lesson':'Explore when ready')+'</span></button>';}).join('')+'</div><p class="math-guidance">Choose any lesson. A little help and a slow pace are welcome.</p></section>';}
 function open(id){const l=mathLessons.find(l=>l.id===id);if(!l)return;ensure();selected=id;state().current=id;const fresh=!state().lessons[id];state().lessons[id]??=normalizeMath({lessons:{[id]:{}}}).lessons[id];if(fresh){while(current().type==='word'&&(state().wordsMet.includes(current().word)||getProgress().playful?.wordsMet.includes(current().word.toLowerCase()))&&index()<steps().length-1)setIndex(index()+1);}save();render();}
 // The lesson after this one in the card order (null after the last).
 const nextLesson=()=>mathLessons[mathLessons.findIndex(l=>l.id===selected)+1]||null;
 function speak(){const st=current();if(st.type==='finish')return;play(st.type==='word'?[{key:'math-word:'+st.word,target:'.math-vocab-word'},{key:'text:'+st.text}]:[{key:'text:'+(st.type==='question'?st.prompt:st.text)}]);}
 function advance(){const st=current(),pr=p();if(st.type==='question'&&!correct(st))return;stop();if(st.type==='word'&&!state().wordsMet.includes(st.word))state().wordsMet.push(st.word);const completed=pr.extra?pr.extraCompleted:pr.completed;if(!completed.includes(index()))completed.push(index());setIndex(Math.min(steps().length-1,index()+1));if(current().type==='finish'){if(pr.extra)pr.extraDone=true;else pr.done=true;}save();render();}
 function html(){const l=lesson(),pr=p(),st=current(),i=index(),total=steps().length;let body='',navigation='';
  if(st.type==='finish')body='<div class="math-star" aria-label="One completion star">★</div><h2>'+esc(pr.extra?l.extra.title:l.title)+'</h2><p>You practised this little lesson. Read and play again whenever you like.</p>'+(nextLesson()?btn('Next lesson · '+esc(nextLesson().title)+' →','next-lesson','','primary'):'')+btn('Back to lessons','back','',nextLesson()?'':'primary')+(l.extra&&!pr.extra?btn('Optional next activity · '+esc(l.extra.title),'extra'):'')+(pr.extra?btn('Return to the first story','core'):'')+btn('Read this lesson again','revisit')+'<p class="math-guidance">A star records practice. It does not verify independent reading or maths mastery.</p>';
  else{
   if(st.type==='word')body=narrationLine(st.word,{key:'math-word:'+st.word,bn:st.meaning,cls:'math-vocab-word'})+mathScene(st.scene)+narrationLine(st.text,{bn:lessonBangla.get(st.text),cls:'sentence math-sentence'})+'<p class="math-guidance">'+(state().wordsMet.includes(st.word)?'Met before · review is optional.':'A new word · listen and look together.')+'</p>';
   else if(st.type==='sentence')body=mathScene(st.scene)+narrationLine(st.text,{bn:st.meaning,cls:'sentence math-sentence'})+(st.equation?'<div class="math-equation" aria-label="Number sentence">'+(Array.isArray(st.equation)?st.equation:[st.equation]).map(e=>'<p>'+esc(e)+'</p>').join('')+'</div>':'');
   else{const a=attempt(st),solved=correct(st),selectedChoice=pr.answers[st.id],choices=a.misses>=2&&!solved?st.choices.filter(c=>c.id===st.answer||c.id===st.choices.find(c=>c.id!==st.answer).id):st.choices;body=mathScene(st.scene)+narrationLine(st.prompt,{bn:st.meaning,cls:'sentence math-sentence'})+'<div class="math-answer-choices" role="group" aria-label="Choose one answer">'+choices.map(c=>'<button class="math-choice '+(selectedChoice&&c.id===st.answer?'correct':selectedChoice===c.id?'retry':'')+'" data-action="stages-math-answer" data-value="'+esc(c.id)+'" '+' aria-label="'+esc(c.label)+'">'+mathChoice(c)+'</button>').join('')+'</div><p class="math-feedback '+(solved?'correct':'')+'" role="status">'+(solved?'✓ '+esc(st.feedback):a.misses?'Thank you for trying. '+esc(st.hint.replace('Thank you for trying. ','')):'Look, then choose.')+'</p>'+(a.misses&&!solved?'<p class="math-demonstration">The answer is <b>'+esc(st.choices.find(c=>c.id===st.answer).label)+'</b>. '+esc(st.feedback)+(a.misses>=2?' Try again with two choices.':'')+'</p>':'');}
   body+=narrationControls()+'<div class="math-audio-controls">'+btn('Stop','stop')+(documentHasMotion(st.scene)?btn('Show action · Replay','action'):'')+'</div>';
   navigation='<div class="math-navigation">'+btn('← Previous','previous',i===0?'disabled':'')+'<span>'+(i+1)+' of '+(total-1)+'</span>'+btn(st.type==='question'&&i===total-2?'Finish ★':'Next →','next',st.type==='question'&&!correct(st)?'disabled':'','primary')+'</div>';
  }
  return '<div class="lesson-head">'+btn('← English for Math','back')+'<span class="lesson-meta" id="save-status">'+(isSaved()?'Saved automatically':'Progress not saved')+'</span></div><section class="activity math-player" data-math-lesson="'+l.id+'" '+(st.type==='finish'?'':'data-narration-step="math:'+l.id+':'+(pr.extra?'extra':'core')+':'+i+'" ')+'data-math-step="'+i+'" data-math-type="'+st.type+'"><div class="eyebrow">'+(pr.extra?'Optional later activity':st.type==='word'?'Meet one word':st.type==='question'?'A little question':'Read and look')+'</div><h1>'+esc(l.title)+'</h1>'+body+navigation+'<p id="audio-status" class="status" role="status"></p></section>';
 }
 function documentHasMotion(scene){return ['flowers-join','bird-away','cake-share','cup-fill','clock-move'].includes(scene);}
 function bind(){const root=document.querySelector('.math-player');if(!root)return;const key=selected+':'+p().extra+':'+index();if(lastBound!==key){stopMotion();lastBound=key;if(documentHasMotion(current().scene))stopMotion=animateMathScene(root);}}
 function handle(d){const action=d.action.replace('stages-math-','');
  if(action==='open'){stop();open(d.id);}else if(action==='audio')speak();else if(action==='stop')stop();else if(action==='action'){stopMotion();stopMotion=animateMathScene(document.querySelector('.math-player'));}
  else if(action==='next')advance();else if(action==='previous'){stop();setIndex(Math.max(0,index()-1));save();render();}
  else if(action==='level'){ensure();if(![0,1,2].includes(Number(d.level)))return;state().level=Number(d.level);save();render(false);}
  else if(action==='answer'){const st=current();if(st.type!=='question'||!st.choices.some(c=>c.id===d.value))return;if(correct(st)){stop();play([{key:d.value===st.answer?'at-say:praise':'at-say:retry'}]);return;}/* answered: taps still respond, without a new score */stop();const a=attempt(st),right=d.value===st.answer;a.tries++;if(a.firstCorrect===null)a.firstCorrect=right;onAttempt(mathQuestionId(lesson(),st),right,a.assisted);if(!right){a.misses++;a.assisted=true;}p().answers[st.id]=d.value;save();render(false);play([{key:(right?'math-feedback:':'math-hint:')+mathQuestionId(lesson(),st),target:'.math-feedback'},...(!right&&a.misses>=2?[{key:'math-demo:'+mathQuestionId(lesson(),st),target:'.math-demonstration'}]:[])]);if(right)document.querySelector('[data-action=stages-math-next]')?.focus({preventScroll:true});}
  else if(action==='extra'&&lesson().extra){stop();p().extra=true;save();render();}else if(action==='core'){stop();p().extra=false;save();render();}else if(action==='revisit'){stop();setIndex(0);save();render();}
   else if(action==='next-lesson'&&nextLesson()){stop();open(nextLesson().id);}
 }
 function parentReport(){if(!getProgress().math)return '';const math=getProgress().math;return '<section class="side-card"><h2>English for Math · This profile</h2><p>'+mathLessons.filter(l=>math.lessons[l.id]?.done).length+' of 12 core lessons practised. Answers record practice, not independent reading or maths mastery.</p><p>Learning level: '+esc(mathLevels[math.level].label)+'</p><ul>'+mathLessons.filter(l=>math.lessons[l.id]).map(l=>{const pr=math.lessons[l.id],misses=Object.values(pr.attempts).reduce((n,a)=>n+a.misses,0);return '<li><b>'+esc(l.title)+'</b> · '+esc(l.skill)+' · '+(pr.done?'core practice complete':'saved step '+(pr.step+1))+' · '+misses+' missed answers'+(Object.values(pr.attempts).some(a=>a.assisted)?' · some answers with help':'')+'</li>';}).join('')+'</ul><p>Missed maths-language questions appear in Often missed and Due for review. Revisit the same picture, say the English sentence together, then count or compare.</p></section>';}
 return{home,open,html,handle,bind,parentReport,cancel:()=>{stopMotion();stopMotion=()=>{};lastBound=null;}};
}
